-- 2. RLS 7 类 policy (per v0.92 + v0.97 DROP IF EXISTS 兼容 PG 9.5+)
-- 模板: 复制到 14 张表 + 改 table name
-- ==========================================
ALTER TABLE agent_relationships ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_relationships FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS agent_sessions_select ON agent_relationships;
CREATE POLICY agent_sessions_select ON agent_relationships
    FOR SELECT
    USING (
        tenant_id::text = current_setting('app.current_tenant_id', true)
        OR current_setting('app.is_admin', true) = 'true'
    );

DROP POLICY IF EXISTS agent_sessions_insert ON agent_relationships;
CREATE POLICY agent_sessions_insert ON agent_relationships
    FOR INSERT
    WITH CHECK (
        tenant_id::text = current_setting('app.current_tenant_id', true)
        OR current_setting('app.is_admin', true) = 'true'
    );

DROP POLICY IF EXISTS agent_sessions_update ON agent_relationships;
CREATE POLICY agent_sessions_update ON agent_relationships
    FOR UPDATE
    USING (
        tenant_id::text = current_setting('app.current_tenant_id', true)
        OR current_setting('app.is_admin', true) = 'true'
    )
    WITH CHECK (
        tenant_id::text = current_setting('app.current_tenant_id', true)
        OR current_setting('app.is_admin', true) = 'true'
    );

DROP POLICY IF EXISTS agent_sessions_delete ON agent_relationships;
CREATE POLICY agent_sessions_delete ON agent_relationships
    FOR DELETE
    USING (
        current_setting('app.is_admin', true) = 'true'
    );

-- ==========================================
-- 3. RLS policy 占位: 跨 schema_name 隔离 + platform_admin override
-- ==========================================
DROP POLICY IF EXISTS agent_sessions_schema_isolation ON agent_relationships;
CREATE POLICY agent_sessions_schema_isolation ON agent_relationships
    FOR ALL
    USING (
        schema_name = current_setting('app.current_schema_name', true)
        OR current_setting('app.is_admin', true) = 'true'
    );

DROP POLICY IF EXISTS agent_sessions_platform_admin ON agent_relationships;
CREATE POLICY agent_sessions_platform_admin ON agent_relationships
    FOR ALL
    TO platform_admin
    USING (true)
    WITH CHECK (true);

COMMIT;
