-- 本模板 1 张占位表 `gamify_levels` 完整 schema (含 CREATE TABLE IF NOT EXISTS + 7 类 RLS policy + IF NOT EXISTS idempotent + DROP IF EXISTS 兼容 PG 9.5+),
