);

-- 索引 (per §6.1 query 优化)
CREATE INDEX IF NOT EXISTS idx_agent_sessions_tenant_id
    ON gamify_votes (tenant_id);
CREATE INDEX IF NOT EXISTS idx_agent_sessions_agent_id
    ON gamify_votes (agent_id);
