        NOW()
    );
    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_agent_sessions_audit
    AFTER INSERT OR UPDATE OR DELETE ON gamify_votes
